-- ============================================================
-- 电商数据智能分析 Agent —— 初始化脚本
--
-- 作用：建库建表 + 灌入样例数据，别人克隆完项目就能跑通。
-- 导入：
--     mysql -u root -p < sql/00_init.sql
-- 或在 MySQL 客户端里：
--     source sql/00_init.sql;
--
-- 可重复执行：脚本开头会 DROP 同名表再重建，不会报"表已存在"。
--
-- 样例数据说明：
--   事实表 user_behavior 从真实公开数据集（淘宝用户行为 UserBehavior）抽样而来：
--   425 条记录，覆盖 pv / fav / cart / buy 四类行为、跨 4 个自然日，
--   并保留了购买频次最高的两位用户。真实数据集约 60 万行、时间跨度
--   2017-11-25 ~ 2017-12-03，想跑真实规模请见 README「数据导入」。
--   三张维表（users / products / categories）只有 ID 是真实的，
--   会员等级 / 城市 / 注册时间 / 商品名 / 价格 / 类目名是按业务常识生成的
--   演示属性（由稳定哈希生成，重复执行结果一致），用于支撑分层、客单价、
--   商品推荐这类需要维表字段的分析。
--
-- behavior_count 说明：真实数据集里这一列全为 0，属于历史遗留脏列。
--   它留在表里（保持和线上结构一致），但通过 .env 的 HIDDEN_COLUMNS
--   从提示词里屏蔽掉，避免模型选中它得出错误结论。
-- ============================================================

CREATE DATABASE IF NOT EXISTS taobao_analysis
  DEFAULT CHARACTER SET utf8mb4
  COLLATE utf8mb4_0900_ai_ci;

USE taobao_analysis;

-- ------------------------------------------------------------
-- 1. 类目维表
-- ------------------------------------------------------------
DROP TABLE IF EXISTS categories;
CREATE TABLE categories (
  category_id BIGINT      NOT NULL COMMENT '商品类目ID',
  name        VARCHAR(16) NOT NULL COMMENT '类目名称',
  PRIMARY KEY (category_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品类目维表';

-- ------------------------------------------------------------
-- 2. 用户维表
-- ------------------------------------------------------------
DROP TABLE IF EXISTS users;
CREATE TABLE users (
  user_id     BIGINT       NOT NULL COMMENT '用户ID',
  member_level VARCHAR(8)  NOT NULL DEFAULT '普通' COMMENT '会员等级：普通 / 银卡 / 金卡 / 钻石',
  city        VARCHAR(16)  NOT NULL DEFAULT '' COMMENT '所在城市',
  register_at DATETIME     DEFAULT NULL COMMENT '注册时间',
  PRIMARY KEY (user_id),
  KEY idx_member_level (member_level)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户维表';

-- ------------------------------------------------------------
-- 3. 商品维表
-- ------------------------------------------------------------
DROP TABLE IF EXISTS products;
CREATE TABLE products (
  item_id     BIGINT        NOT NULL COMMENT '商品ID',
  item_name   VARCHAR(64)   NOT NULL COMMENT '商品名称',
  category_id BIGINT        DEFAULT NULL COMMENT '所属类目ID，关联 categories.category_id',
  price       DECIMAL(10,2) NOT NULL DEFAULT 0.00 COMMENT '售价（元）',
  PRIMARY KEY (item_id),
  KEY idx_products_category (category_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品维表';

-- ------------------------------------------------------------
-- 4. 用户行为事实表（核心表）
--    behavior_type 取值：pv=浏览 / fav=收藏 / cart=加购 / buy=购买
--    date_only 需要数据导入时自行赋值，抽样数据已带值；
--    若换了数据源，可按 DATE(`date`) 回填，否则按天聚合的问题会查不到数据。
-- ------------------------------------------------------------
DROP TABLE IF EXISTS user_behavior;
CREATE TABLE user_behavior (
  id             BIGINT      NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  user_id        BIGINT      NOT NULL                COMMENT '用户ID',
  item_id        BIGINT      NOT NULL                COMMENT '商品ID',
  category_id    BIGINT      NOT NULL                COMMENT '商品类目ID',
  behavior_type  VARCHAR(20) NOT NULL                COMMENT '用户行为类型：pv=浏览 / fav=收藏 / cart=加购 / buy=购买',
  `timestamp`    BIGINT      DEFAULT NULL            COMMENT '行为发生时间戳（秒级）',
  `date`         DATETIME    DEFAULT NULL            COMMENT '行为发生日期时间',
  date_only      DATE        DEFAULT NULL            COMMENT '行为发生日期（仅年月日，按天聚合用这列）',
  behavior_count BIGINT      NOT NULL                COMMENT '遗留脏列，全为 0，已通过 HIDDEN_COLUMNS 屏蔽',
  PRIMARY KEY (id),
  KEY idx_behavior_type (behavior_type),
  KEY idx_date_only (date_only),
  KEY idx_user_id (user_id),
  KEY idx_item_id (item_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户行为明细事实表（pv/fav/cart/buy）';

