-- ------------------------------------------------------------
-- 6. 自检（应看到 pv / fav / cart / buy 四类行为，以及维表属性非空）
-- ------------------------------------------------------------
SELECT behavior_type AS 行为类型, COUNT(*) AS 数量
FROM user_behavior
GROUP BY behavior_type
ORDER BY 数量 DESC;

SELECT '用户数' AS 指标, COUNT(*) AS 值 FROM users
UNION ALL SELECT '商品数', COUNT(*) FROM products
UNION ALL SELECT '类目数', COUNT(*) FROM categories
UNION ALL SELECT '商品最低价', MIN(price) FROM products
UNION ALL SELECT '商品最高价', MAX(price) FROM products;
